// === Tab: mySketch ===
let cols, rows;
let space = 30;

function setup() {
  createCanvas(800, 800);

  cols = floor(width / space);
  rows = floor(height / space);

  noFill();
}

function draw() {

  // dark blue-gray background
  background(8, 10, 18, 30);

  blendMode(ADD);

  for (let i = 0; i < cols; i++) {
    for (let j = 0; j < rows; j++) {

      let x = i * space + space / 2;
      let y = j * space + space / 2;

      let n = noise(
        i * 0.08,
        j * 0.08,
        frameCount * 0.01
      );

      let angle = n * TWO_PI * 2;

      let offsetX = cos(angle) * 8;
      let offsetY = sin(angle) * 8;

      let pulse = sin(
        frameCount * 0.03 +
        i * 0.25 +
        j * 0.18
      );

      let s = map(pulse, -1, 1, 2, 16);

      let c1 = color(120, 160, 255, 18); // dusty blue
      let c2 = color(255, 140, 180, 14); // muted pink
      let c3 = color(180, 255, 220, 10); // pale mint

      let finalColor;

      if (n < 0.33) {
        finalColor = c1;
      } else if (n < 0.66) {
        finalColor = c2;
      } else {
        finalColor = c3;
      }

      // soft glow layers
      for (let k = 3; k > 0; k--) {

        stroke(finalColor);
        strokeWeight(k * 2);

        circle(
          x + offsetX,
          y + offsetY,
          s * k * 0.6
        );
      }

      // bright center
      stroke(255, 255, 255, 90);
      strokeWeight(1);

      circle(
        x + offsetX,
        y + offsetY,
        s * 0.6
      );
    }
  }

  blendMode(BLEND);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);

  cols = floor(width / space);
  rows = floor(height / space);
}

